/** Bounded paths for schema failures at durable boundaries.
 * @since 1.0.0
 */
// A key holding `.` or `[` must not read as a different field, so only an
// identifier renders with a dot; any other key renders as a quoted JSON string,
// matching `canonicalize` and `BoundedJson.admitStrict`.
const renderSegment = (segment) => typeof segment === "number"
    ? `[${segment}]`
    : typeof segment === "symbol"
        ? `[${String(segment)}]`
        : /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(segment)
            ? `.${segment}`
            : `[${JSON.stringify(segment)}]`;
const renderPath = (segments) => segments.reduce((path, segment) => path + renderSegment(segment), "$");
/**
 * Finds the first rejected field in an Effect schema error without rendering
 * the value stored at that field. Follows the first issue branch for at most
 * 64 wrappers, returning the accumulated path when the limit is reached.
 * Field names are caller-controlled and the returned text is not redacted
 * or length-limited.
 *
 * @param error - An Effect schema decode or encode failure.
 * @returns A JSON-style path beginning with $, or $ for a root rejection.
 *
 * @category formatting
 * @since 0.1.0
 */
export const firstPath = (error) => {
    const segments = [];
    let issue = error.issue;
    for (let depth = 0; depth < 64; depth++) {
        switch (issue._tag) {
            case "Pointer":
                for (const segment of issue.path)
                    segments.push(segment);
                issue = issue.issue;
                continue;
            case "Filter":
            case "Encoding":
                issue = issue.issue;
                continue;
            case "Composite":
            case "AnyOf": {
                const first = issue.issues[0];
                if (first === undefined)
                    return renderPath(segments);
                issue = first;
                continue;
            }
            default:
                return renderPath(segments);
        }
    }
    return renderPath(segments);
};
